// tests/lod2_roof_editing.test.ts
var source = {
  schemaVersion: "lod2-roof-source.v1",
  sourceSha256: "a".repeat(64),
  buildingId: "fixture",
  sourceTile: "tile.zip",
  baseY: 6,
  referencePitchDeg: 35,
  footprint: [[[0, 0], [8, 0], [8, 8], [0, 8], [0, 0]]],
  faces: [
    { face_ref: "f1", polygon_3d_mm: [[0, 0, 6e3], [8e3, 0, 6e3], [8e3, 8e3, 1e4]] },
    { face_ref: "f2", polygon_3d_mm: [[0, 0, 6e3], [8e3, 8e3, 1e4], [0, 8e3, 1e4]] }
  ]
};
var parameters = {
  ...DEFAULT_ROOF_TOOL_PARAMETERS,
  roofType: "imported",
  importedSource: source,
  pitchDeg: 35,
  eavesHeightMm: 6e3,
  overhangMm: 0,
  overhangNorthMm: 0,
  overhangEastMm: 0,
  overhangSouthMm: 0,
  overhangWestMm: 0
};
var points = source.footprint[0].slice(0, -1).map(([x, z]) => ({ x, z, y: 6 }));
test2("original LoD2 shape uses canonical roof meshes, without network or invented structure", async () => {
  const request = buildRoofCalculationRequest(points, parameters);
  const calculation = await requestRoofCalculation(request);
  assert2.deepEqual(calculation.geometry.faces, source.faces);
  assert2.deepEqual(calculation.structure.rafters, []);
  const rendered = createRoofCalculationMeshes(calculation, { objectInstanceId: "roof-fixture", semanticObjectRef: { metadata: { roofParameters: parameters } } });
  assert2.equal(rendered.meshes.length, 1);
  assert2(rendered.meshes.every((m) => m.userData.semanticRoof === true && m.userData.objectInstanceId === "roof-fixture"));
  assert2(rendered.meshes.every((m) => m.userData.existingLod2Roof === true));
  assert2.equal(`#${rendered.meshes[0].material.color.getHexString()}`, LOD2_EXISTING_ROOF_COLOR);
  rendered.geometries.forEach((g) => g.dispose());
  rendered.materials.forEach((m) => m.dispose());
});
test2("solar metadata never changes an untouched LoD2 roof from existing-white to design-red", async () => {
  const calculation = await requestRoofCalculation(buildRoofCalculationRequest(points, parameters));
  const rendered = createRoofCalculationMeshes(calculation, {
    semanticObjectRef: {
      metadata: {
        roofParameters: parameters,
        solar: { moduleId: "pv-module", selectedFaces: ["f1"] }
      }
    }
  });
  assert2(rendered.meshes.length > 0);
  assert2(rendered.meshes.every((mesh) => mesh.userData.existingLod2Roof === true));
  assert2.equal(`#${rendered.meshes[0].material.color.getHexString()}`, LOD2_EXISTING_ROOF_COLOR);
  rendered.geometries.forEach((g) => g.dispose());
  rendered.materials.forEach((m) => m.dispose());
});
test2("slope edit produces new persisted geometry but retains original source", async () => {
  const original = JSON.stringify(source);
  const first = await requestRoofCalculation(buildRoofCalculationRequest(points, parameters));
  const edited = await requestRoofCalculation(buildRoofCalculationRequest(points, { ...parameters, pitchDeg: 45 }));
  assert2.notEqual(first.input_fingerprint, edited.input_fingerprint);
  assert2(edited.summary.maximum_height_mm > first.summary.maximum_height_mm);
  assert2.equal(JSON.stringify(source), original);
  const rendered = createRoofCalculationMeshes(edited, {
    semanticObjectRef: { metadata: { roofParameters: parameters, solar: { selectedFaces: ["f1"] } } }
  });
  assert2(rendered.meshes.every((mesh) => mesh.userData.existingLod2Roof === false));
  assert2.equal(rendered.meshes[0].material.color.getHex(), 12142364);
  rendered.geometries.forEach((g) => g.dispose());
  rendered.materials.forEach((m) => m.dispose());
  const saved = JSON.parse(JSON.stringify({ ...parameters, pitchDeg: 45 }));
  assert2.equal(persistedRoofQuickSettings({ roofParameters: saved }, parameters).roofType, "imported");
  const reloaded = await requestRoofCalculation(buildRoofCalculationRequest(points, saved));
  assert2.deepEqual(reloaded.geometry, edited.geometry);
});
test2("courtyard cannot silently become a filled standard roof; invalid sources fail closed", async () => {
  const courtyard = { ...source, footprint: [...source.footprint, [[2, 2], [6, 2], [6, 6], [2, 6], [2, 2]]] };
  await assert2.rejects(requestRoofCalculation(buildRoofCalculationRequest(points, { ...parameters, importedSource: courtyard, roofType: "gable" })), /Innenhof/);
  await assert2.rejects(requestRoofCalculation(buildRoofCalculationRequest(points.slice(0, -1), parameters)), /Dachumriss/);
  assert2.equal(importedRoofSource({ ...source, faces: [{ polygon_3d_mm: [[NaN, 0, 0]] }] }), void 0);
});
test2("LoD2 overhang extends only boundary vertices and keeps the source immutable", async () => {
  const original = JSON.stringify(source);
  const calculation = await requestRoofCalculation(buildRoofCalculationRequest(points, {
    ...parameters,
    overhangMm: 500,
    overhangNorthMm: 500,
    overhangEastMm: 500,
    overhangSouthMm: 500,
    overhangWestMm: 500
  }));
  const vertices = calculation.geometry.faces.flatMap((face) => face.polygon_3d_mm);
  assert2(Math.min(...vertices.map((point) => point[0])) < 0);
  assert2(Math.max(...vertices.map((point) => point[0])) > 8e3);
  assert2(Math.min(...vertices.map((point) => point[1])) < 0);
  assert2(Math.max(...vertices.map((point) => point[1])) > 8e3);
  assert2.equal(JSON.stringify(source), original);
  assert2.match(String(calculation.input_fingerprint), /:500$/);
});
test2("editable semantic roof footprints retain courtyard rings across load and save", () => {
  const coordinates = [
    [[0, 0], [10, 0], [10, 10], [0, 10], [0, 0]],
    [[3, 3], [7, 3], [7, 7], [3, 7], [3, 3]]
  ];
  const rings = polygonAreaRingsFromFootprint({
    type: "Polygon",
    coordinates,
    baseY: 12
  }, 0);
  assert2.equal(rings.length, 2);
  assert2(rings.every((ring) => ring.every((point) => point.y === 12)));
  assert2.deepEqual(polygonAreaClosedRingCoordinates(rings[0], rings.slice(1)), coordinates);
  assert2.deepEqual(polygonAreaRingsFromFootprint({
    type: "Polygon",
    coordinates: [coordinates[0].slice(0, 2), coordinates[1]]
  }, 0), []);
});
test2("local flat-roof calculation triangulates around courtyards and has a stable persisted version", () => {
  const outerRing = [[0, 0], [10, 0], [10, 10], [0, 10]].map(([x, z]) => ({ x, y: 6, z }));
  const holeRing = [[3, 3], [7, 3], [7, 7], [3, 7]].map(([x, z]) => ({ x, y: 6, z }));
  const calculation = createFlatRoofCalculation(outerRing, 6e3, [holeRing], 240);
  const faces = calculation.geometry.faces;
  assert2(faces.length > 1);
  const area5 = faces.reduce((sum, face) => sum + Number(face.plan_area_m2), 0);
  assert2(Math.abs(area5 - 84) < 1e-7);
  for (const face of faces) {
    const centroidX = face.polygon_3d_mm.reduce((sum, point) => sum + point[0], 0) / face.polygon_3d_mm.length / 1e3;
    const centroidZ = face.polygon_3d_mm.reduce((sum, point) => sum + point[1], 0) / face.polygon_3d_mm.length / 1e3;
    assert2(!(centroidX > 3 && centroidX < 7 && centroidZ > 3 && centroidZ < 7));
  }
  assert2.match(String(calculation.input_fingerprint), /^flat-courtyard-v1:/);
  assert2.equal(
    calculation.input_fingerprint,
    createFlatRoofCalculation(outerRing, 6e3, [holeRing], 240).input_fingerprint
  );
  assert2.notEqual(
    calculation.input_fingerprint,
    createFlatRoofCalculation(outerRing, 6e3, [], 240).input_fingerprint
  );
  assert2.equal(calculation.structure.bearing_model.purlin_vertical_reference, "roof_zone_top");
  assert2.equal(calculation.roof_build_up.layers[0].thickness_mm, 240);
});

