  const b = caps.geometry.boundingBox;
  assert4(Math.abs(b.max.y - 0.7) < 1e-6);
  assert4(Math.abs(b.min.x - 0.2) < 1e-6);
  assert4(Math.abs(b.max.x - 0.8) < 1e-6);
  assert4(Math.abs(b.min.z - 0.2) < 1e-6);
