  const facade2 = {
    start: [0, 0],
    end: [4, 0],
    minimumY: 2,
    maximumY: 3,
    facadeRole: "connector",
    topProfile: [[0, 3], [4, 3]],
    bottomProfile: [[0, 2], [4, 2]]
  };
  const wallCells = [];
  for (let x = 0; x < 4; x++) wallCells.push([x, 2, 0]);
