  const raised = roof4([[0, 30, 0], [10, 30, 0], [10, 30, 10], [0, 30, 10]], "raised");
  const after = buildSolarLayout(raised, JSON.parse(JSON.stringify(settings)));
  assert6.equal(before.panels.length, after.panels.length);
  after.panels.forEach((p, i) => assert6(Math.abs(p.center.y - before.panels[i].center.y - 20) < 1e-6));
