test6("imported roof facets merge into one draw without losing triangles or height", () => {
  const a = roof4([[0, 10, 0], [10, 10, 0], [10, 15, 10]]);
  a.geometry.faces.push(roof4([[0, 10, 0], [10, 15, 10], [0, 15, 10]]).geometry.faces[0]);
  const result = createRoofCalculationMeshes(a);
  assert6.equal(result.meshes.length, 1);
  assert6.equal(result.geometries.length, 1);
  const baseline = createRoofCalculationMeshes(a, { mergeParts: false });
  const g = result.geometries[0];
  assert6.equal(g.index.count, baseline.geometries.reduce((n, g2) => n + g2.index.count, 0));
  assert6(g.boundingBox.max.y >= 15);
  baseline.geometries.forEach((g2) => g2.dispose());
  baseline.materials.forEach((m) => m.dispose());
  result.geometries.forEach((g2) => g2.dispose());
  result.materials.forEach((m) => m.dispose());
});
test6("parametric roof batching retains every triangle, normal, UV, bound and part reference", () => {
  const members = Array.from({ length: 1e3 }, (_, i) => ({
    member_ref: `member-${i}`,
    start_3d_mm: [i * 50, 0, 9e3],
    end_3d_mm: [i * 50, 1e4, 1e4],
    section_mm: { width: 80, height: 200 },
    height_axis_3d: [0, 0, 1]
  }));
  const calculation = {
    ...flat,
    roof_type: "pent",
    structure: { rafters: members, purlins: members.slice(0, 3) },
    roof_build_up: { counter_battens: members, tile_battens: members, exterior_offset_mm: 100 }
  };
  const ref = { id: "semantic-roof" };
  const baseline = createRoofCalculationMeshes(calculation, { mergeParts: false, semanticObjectRef: ref, objectInstanceId: "roof-1" });
  const result = createRoofCalculationMeshes(calculation, { semanticObjectRef: ref, objectInstanceId: "roof-1" });
  assert6(baseline.meshes.length > 5e3);
  assert6(result.meshes.length < 10);
  const originalParts = new Map(baseline.meshes.map((m) => [m.userData.roofPart, m]));
  let triangleCount = 0;
  for (const mesh of result.meshes) {
    assert6.equal(mesh.userData.semanticObjectRef, ref);
    assert6.equal(mesh.userData.objectInstanceId, "roof-1");
    const parts = mesh.userData.roofParts ?? [{ part: mesh.userData.roofPart, indexOffset: 0, indexCount: mesh.geometry.index.count }];
    const bounds = new Box3();
    for (const part of parts) {
      const original = originalParts.get(part.part);
      assert6(original);
      bounds.union(original.geometry.boundingBox);
      assert6.equal(part.indexCount, original.geometry.index.count);
      for (let i = 0; i < part.indexCount; i++) {
        const a = original.geometry.index.getX(i), b = mesh.geometry.index.getX(part.indexOffset + i);
        for (const name of Object.keys(original.geometry.attributes)) {
          const source2 = original.geometry.getAttribute(name), target = mesh.geometry.getAttribute(name);
          for (let component = 0; component < source2.itemSize; component++)
            assert6.equal(target.array[b * target.itemSize + component], source2.array[a * source2.itemSize + component]);
        }
      }
      triangleCount += part.indexCount / 3;
      originalParts.delete(part.part);
    }
    assert6(mesh.geometry.boundingBox.equals(bounds));
  }
  assert6.equal(originalParts.size, 0);
  assert6.equal(triangleCount, baseline.geometries.reduce((sum, g) => sum + g.index.count / 3, 0));
  for (const rendered of [baseline, result]) {
    rendered.geometries.forEach((g) => g.dispose());
    rendered.materials.forEach((m) => m.dispose());
  }
});
function chunk2(x = 0, refs = []) {
  const result = normalizeChunkApiBatchResult({ ok: true, chunks: [{ chunk: {
    projectId: "test",
    worldId: "test",
    chunkX: x,
    chunkY: 0,
    chunkZ: 0,
    chunkKey: `${x}:0:0`,
    chunkSize: 16,
    cellSize: 1,
    cells: Array(4096).fill(0),
    palette: [{ blockTypeId: "lod2_exterior_wall" }],
    objectRefs: refs
  } }] }, null, { projectId: "test", worldId: "test" });
  assert6(result.ok);
  return createRuntimeChunkContent(result.chunks[0]);
}
test6("roof index rebuilds on actual content changes, not camera reads or visibility updates", () => {
  const registry = createChunkRegistry({ maxChunks: 10 });
  const ref = { objectTypeId: "building_roof", objectInstanceId: "r", metadata: { lod2BuildingId: "b" }, anchor: { x: 0, y: 20, z: 0 }, dimensions: { x: 32, y: 4, z: 16 } };
  const c = chunk2(0, [ref]);
  registry.setChunk(c);
  const index = createLod2RoofIndex((c2) => c2.raw.objectRefs);
  for (let i = 0; i < 100; i++) {
    registry.getChunk(c.chunkKey);
    registry.setVisibleChunkKeys([c.chunkKey]);
    assert6.equal(index.query(registry, c).length, 1);
  }
  assert6.equal(index.getBuildCount(), 1);
  registry.setChunk(chunk2(1));
  assert6.equal(index.query(registry, c).length, 1);
  assert6.equal(index.getBuildCount(), 2);
  registry.deleteChunk(c.chunkKey);
  assert6.equal(index.query(registry, c).length, 0);
  assert6.equal(index.getBuildCount(), 3);
  registry.clear();
  index.query(registry, c);
  assert6.equal(index.getBuildCount(), 4);
});
